  "id": "ch01.fact.1",
  "kind": "testable_fact",
  "label": "The 2007 iPhone launch framed the device as a practical convergence of phone, iPod, and internet communicator, not as a permanent social-feed companion.",
  "supportsClaimTypes": [
    "book_thesis",
    "core_idea",
    "core_move",
    "hook",
    "breakdown_claim",
    "quiz_prompt",
    "quiz_explanation",
