  "id": "ch01.fact.2",
  "kind": "testable_fact",
  "label": "A platform can provide genuine convenience while still extracting attention far beyond the value of that convenience.",
  "supportsClaimTypes": [
    "book_thesis",
    "core_idea",
    "core_move",
    "hook",
    "breakdown_claim",
    "quiz_prompt",
    "quiz_explanation",
